var e=[{title:`La posizione base nella corsa`,text:`Corri eretto e rilassato, con una leggera inclinazione naturale in avanti di tutto il corpo e le braccia che oscillano con facilità. Tieni le spalle sciolte e non allungarti troppo in avanti a ogni passo. La tua falcata dovrebbe risultare coordinata alla velocità che scegli, senza forzarla in un modello fisso.`},{title:`Cadenza e appoggio del piede`,text:`La cadenza è il numero di passi che fai al minuto. Alcuni corridori possono trarre beneficio da una piccola modifica, ma nessuna regola dice che tutti devono correre a 180 passi al minuto. Gli appoggi di tallone, mesopiede e avampiede distribuiscono le forze in modo diverso, e le evidenze non sostengono l’idea di far passare ogni corridore sano a un solo schema di atterraggio.`},{title:`Intervalli corsa-camminata`,text:`Da principiante, potresti alternare un minuto di jogging facile con due minuti di camminata per 15–20 minuti, più riscaldamento e defaticamento. Nel corso di diverse settimane, allunga le parti di jogging. Progredisci in base a tempo, fiducia e a quanto ti sembra duro, e fai pause di camminata ogni volta che vuoi. La giusta quantità di partenza dipende da quanto sei stato attivo, da come il tuo corpo la gestisce e dalla superficie, quindi non esiste un programma fisso che tutti devono seguire.`},{title:`Gli sprint sono un’abilità a parte`,text:`Le accelerazioni veloci richiedono molto di più a muscoli e tendini. Costruisci una forma di corsa di base prima di fare sprint a piena velocità e riscaldati più a lungo quando aggiungi sforzi più veloci. Fermati se senti un dolore acuto o che peggiora. Scegli scarpe e un percorso adatti alla superficie e alle condizioni, e se la corsa è in conflitto con i tuoi limiti di impatto o non hai un percorso sicuro, fai condizionamento a basso impatto.`}];var o=[{label:`Revisione sistematica: tecnica di appoggio del piede e rischio di infortunio`,url:`https://pubmed.ncbi.nlm.nih.gov/34527750/`},{label:`Revisione sistematica su cadenza di corsa e rischio di infortunio`,url:`https://pubmed.ncbi.nlm.nih.gov/40964543/`},{label:`CDC: raccomandazioni sull’attività fisica per gli adulti`,url:`https://www.cdc.gov/physical-activity-basics/guidelines/adults.html`}];var t={sections:e,sources:o};export{t as default,e as sections,o as sources};